using System.Security.Claims; using MaintenancePRO.Api.Contracts; using MaintenancePRO.Api.Data; using MaintenancePRO.Api.Models; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore;
namespace MaintenancePRO.Api.Controllers;
[ApiController,Route("api/equipment"),Authorize]
public sealed class EquipmentController(AppDbContext db):ControllerBase {
 [HttpGet] public async Task<IActionResult> List([FromQuery]string? search,[FromQuery]EquipmentStatus? status,[FromQuery]int page=1,[FromQuery]int pageSize=20){page=Math.Max(1,page);pageSize=Math.Clamp(pageSize,1,100);var q=db.Equipments.AsNoTracking();if(!string.IsNullOrWhiteSpace(search)){var s=search.Trim();q=q.Where(x=>x.Code.Contains(s)||x.Name.Contains(s)||x.Location.Contains(s)||x.Category.Contains(s));}if(status.HasValue)q=q.Where(x=>x.Status==status);var total=await q.CountAsync();return Ok(new{page,pageSize,total,items=await q.OrderBy(x=>x.Code).Skip((page-1)*pageSize).Take(pageSize).ToListAsync()});}
 [HttpGet("{id:int}")] public async Task<IActionResult> Get(int id){var x=await db.Equipments.AsNoTracking().FirstOrDefaultAsync(x=>x.Id==id);return x==null?NotFound():Ok(x);}
 [HttpGet("{id:int}/history")] public async Task<IActionResult> History(int id){if(!await db.Equipments.AnyAsync(x=>x.Id==id))return NotFound();return Ok(new{breakdowns=await db.Breakdowns.AsNoTracking().Where(x=>x.EquipmentId==id).OrderByDescending(x=>x.ReportedUtc).Select(x=>new{id=x.Id,x.Title,x.Description,x.Severity,x.Status,x.ReportedUtc,x.ResolvedUtc}).ToListAsync(),interventions=await db.Interventions.AsNoTracking().Where(x=>x.EquipmentId==id).OrderByDescending(x=>x.CreatedUtc).ToListAsync()});}
 [HttpPost,Authorize(Policy="ManageEquipment")] public async Task<IActionResult> Create(CreateEquipmentRequest r){var code=r.Code.Trim().ToUpperInvariant();if(await db.Equipments.AnyAsync(x=>x.Code==code))return Conflict(new{message="Ce code équipement existe déjà."});var x=new Equipment{Code=code,Name=r.Name.Trim(),Location=r.Location.Trim(),Category=r.Category.Trim(),Manufacturer=r.Manufacturer,Model=r.Model,SerialNumber=r.SerialNumber,CommissionedUtc=r.CommissionedUtc,Notes=r.Notes};db.Equipments.Add(x);await db.SaveChangesAsync();Audit("EquipmentCreated","Equipment",x.Id.ToString());await db.SaveChangesAsync();return CreatedAtAction(nameof(Get),new{id=x.Id},x);}
 [HttpPut("{id:int}"),Authorize(Policy="ManageEquipment")] public async Task<IActionResult> Update(int id,UpdateEquipmentRequest r){var x=await db.Equipments.FindAsync(id);if(x==null)return NotFound();x.Name=r.Name.Trim();x.Location=r.Location.Trim();x.Category=r.Category.Trim();x.Manufacturer=r.Manufacturer;x.Model=r.Model;x.SerialNumber=r.SerialNumber;x.CommissionedUtc=r.CommissionedUtc;x.Notes=r.Notes;x.Status=r.Status;x.UpdatedUtc=DateTime.UtcNow;await db.SaveChangesAsync();Audit("EquipmentUpdated","Equipment",id.ToString());await db.SaveChangesAsync();return Ok(x);}
 [HttpDelete("{id:int}"),Authorize(Policy="AdminOnly")] public async Task<IActionResult> Delete(int id){var x=await db.Equipments.FindAsync(id);if(x==null)return NotFound();if(await db.Breakdowns.AnyAsync(b=>b.EquipmentId==id))return Conflict(new{message="Équipement référencé dans l'historique; archive-le plutôt que le supprimer."});db.Equipments.Remove(x);Audit("EquipmentDeleted","Equipment",id.ToString());await db.SaveChangesAsync();return NoContent();}
 private void Audit(string action,string type,string id)=>db.AuditEvents.Add(new AuditEvent{ActorUserId=User.FindFirstValue(ClaimTypes.NameIdentifier),Action=action,EntityType=type,EntityId=id,IpAddress=HttpContext.Connection.RemoteIpAddress?.ToString()});
}
